class VoidBrowserController {
  Future<void> Function(String path)? _scrollToTrack;

  /// Best-effort snapshot of the current browser viewport.
  ///
  /// Used by [VoidScreen] to decide whether to expose the jump-to-now-playing
  /// action when the playing row is off-screen.
  final ValueNotifier<BrowserScrollMetrics> scrollMetricsNotifier =
      ValueNotifier(const BrowserScrollMetrics(
    offset: 0,
    viewportDimension: 0,
  ));

  /// Centre the row for [path] in view; no-op when the browser is unmounted.
  Future<void> scrollToTrack(String path) async =>
      await _scrollToTrack?.call(path);

  void dispose() => scrollMetricsNotifier.dispose();
}

